  async function runMaterialAction(modal,state,action,materialId){const item=selectMaterial(state,materialId);if(!item)return;if(action==='continue-study'||action==='create-table-revision'){closeModal(modal);if(typeof window.v3LibraryOpenText==='function')await window.v3LibraryOpenText(item.text_id,{resume:true});return;}if(action==='continue-correction'){closeModal(modal);if(window.StudioMediaPackage&&window.StudioMediaPackage.openWorkspace)await window.StudioMediaPackage.openWorkspace(item.package_id,item.binding_track_id);return;}if(action==='unarchive'&&item.import_receipt_id){await restoreLibraryProjection(item.import_receipt_id);return open({view:'materials',materialId:item.material_id});}if(action==='repair-binding'&&item.import_receipt_id){await repairTextMediaBinding(item.import_receipt_id);return open({view:'materials',materialId:item.material_id});}state.intent=action==='relink-media'?'relink':action==='create-backup'||action==='confirm-backup'?'move-device':action==='recover-from-package'?'restore':'inspect';await renderView(modal,state,'tasks');}
