  async function renderOverview(modal,state){const body=modal.querySelector('#p2PortableBody'),actions=modal.querySelector('#p2PortableActions'),attention=state.catalog.filter(item=>item.continuity_state!=='ready'),ready=state.catalog.filter(item=>item.continuity_state==='ready');actions.innerHTML='';body.innerHTML=`<section class="p4-overview"><div class="p4-overview-stats"><button type="button" data-filter="attention"><strong>${attention.length}</strong><span>${tr('studio.importCenter.needsAttention','Needs attention')}</span></button><button type="button" data-filter="ready"><strong>${ready.length}</strong><span>${tr('studio.importCenter.readyStudy','Ready to study')}</span></button></div>${state.catalog.length?materialCard((attention[0]||ready[0])):`<div class="p2-portable-status p4-empty"><b>${tr('studio.importCenter.emptyTitle','Bring your first material')}</b><span>${tr('studio.importCenter.emptyHelp','Import or restore a checked package. Nothing is uploaded automatically.')}</span><button type="button" data-next="restore">${tr('studio.importCenter.restore','Restore or import')}</button></div>`}</section>`;body.onclick=async event=>{const filter=event.target&&event.target.closest&&event.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;return renderView(modal,state,'materials');}const next=event.target&&event.target.closest&&event.target.closest('[data-next]');if(next&&next.dataset.next==='restore'){state.intent='restore';return renderView(modal,state,'tasks');}if(next)await runMaterialAction(modal,state,next.dataset.next,next.dataset.material);};}
