  async function renderMoveDevice(modal,state,item){const body=modal.querySelector('#p2PortableBody'),actions=modal.querySelector('#p2PortableActions');body.innerHTML=`<section class="p4-wizard" data-task="move-device"><span class="p2-scope-eyebrow">1 → 2 → 3</span><h4>${tr('studio.importCenter.moveTitle','Use on another device')}</h4><p>${tr('studio.importCenter.moveScope','The archive carries immutable transcript/table history. Media bytes stay separate and relink by exact SHA-256.')}</p>${item?continuityRail(item):''}<div id="p4TaskStatus" class="p2-portable-status" aria-live="polite">${item?esc(item.title):tr('studio.importCenter.chooseMaterial','Choose a material first.')}</div></section>`;actions.innerHTML=item?`<button type="button" data-generate>${tr('studio.importCenter.generateArchive','Create checked archive')}</button><button type="button" data-back>${tr('studio.importCenter.back','Back')}</button>`:`<button type="button" data-back>${tr('studio.importCenter.back','Back')}</button>`;actions.onclick=async event=>{const back=actionTarget(event,'[data-back]');if(back){state.intent=null;return renderTasks(modal,state);}const generate=actionTarget(event,'[data-generate]');if(!generate)return;const status=body.querySelector('#p4TaskStatus');generate.disabled=true;try{status.textContent=tr('studio.importCenter.generating','Creating and hashing package…');const built=await exportMaterial(item.material_id,'archive');state.lastGenerated=built.export_receipt;status.innerHTML=`<b>${tr('studio.importCenter.generatedUnconfirmed','Package created — confirm where you saved it.')}</b><span>SHA ${esc(shortSha(built.export_receipt.artifact_sha256))}</span><div class="p4-save-confirm"><button type="button" data-saved="files_icloud">Files / iCloud</button><button type="button" data-saved="files_local">${tr('studio.importCenter.filesLocal','Files on this device')}</button><button type="button" data-saved="share_sheet">${tr('studio.importCenter.shareSheet','Share sheet')}</button><button type="button" data-saved="other">${tr('studio.importCenter.otherDestination','Other')}</button></div>`;}catch(error){status.classList.add('p2-portable-error');status.textContent=formatPortableError(error);generate.disabled=false;}};body.onclick=async event=>{const destination=event.target&&event.target.dataset.saved;if(!destination||!state.lastGenerated)return;await confirmExportSaved(state.lastGenerated.receipt_id,destination);body.querySelector('#p4TaskStatus').innerHTML=`<b>${tr('studio.importCenter.savedConfirmed','Saved copy confirmed for the current material state.')}</b><p>${tr('studio.importCenter.iphoneSteps','On iPhone: open Import Center → Restore → check package → Apply → relink the original media → test playback → cold reopen.')}</p>`;};}
