  async function renderDiagnostics(modal,state){const body=modal.querySelector('#p2PortableBody'),actions=modal.querySelector('#p2PortableActions'),diag=await storageDiagnostics(false),item=selectMaterial(state);body.innerHTML=`<section class="p4-wizard" data-task="inspect"><h4>${tr('studio.importCenter.diagnostics','Storage, delete and recovery diagnostics')}</h4><p>${tr('studio.importCenter.storageTruth','Stored on this device is not the same as backed up.')}</p><dl><dt>${tr('studio.importCenter.usage','Usage')}</dt><dd>${esc(formatBytes(diag.usage_bytes))}</dd><dt>${tr('studio.importCenter.quota','Quota')}</dt><dd>${esc(formatBytes(diag.quota_bytes))}</dd><dt>${tr('studio.importCenter.persistent','Persistent')}</dt><dd>${diag.persisted==null?tr('studio.importCenter.unknown','unknown'):String(diag.persisted)}</dd></dl>${item&&item.import_receipt_id?`<button type="button" data-delete-plan>${tr('studio.importCenter.checkDelete','Check safe deletion')}</button>`:''}<div id="p4TaskStatus" class="p2-portable-status" aria-live="polite"></div><details><summary>${tr('studio.importCenter.technicalDetails','Technical details')}</summary><code>${esc(JSON.stringify({content_free:true,app_version:typeof window!=='undefined'&&window.APP_VERSION||null,schema_version:48,storage:diag,material_count:state.catalog.length,receipt_count:state.exportReceipts.length,status_codes:state.catalog.map(x=>x.continuity_state)},null,2))}</code></details></section>`;actions.innerHTML=`<button type="button" data-export-diagnostics>${tr('studio.importCenter.exportDiagnostics','Export content-free diagnostics')}</button><button type="button" data-persist>${tr('studio.importCenter.requestPersistence','Request persistent storage')}</button><button type="button" data-back>${tr('studio.importCenter.back','Back')}</button>`;body.onclick=async event=>{if(!actionTarget(event,'[data-delete-plan]')||!item.import_receipt_id)return;const plan=await (await readyRepository()).reverseReferencePlan(item.import_receipt_id),safe=importCenterCore().buildDeletePlan({referenced_count:plan.blockers.length,reused_count:Object.values(plan.created||{}).filter(v=>!v).length,created_count:Object.values(plan.created||{}).filter(Boolean).length,external_artifact_known:true});body.querySelector('#p4TaskStatus').textContent=safe.can_delete?tr('studio.importCenter.deleteSafe','Safe to remove only locally created, unreferenced canon after export. External files are never deleted.'):tr('studio.importCenter.deleteBlocked','Deletion is blocked by current references. Nothing changed; export remains available.');};actions.onclick=async event=>{if(actionTarget(event,'[data-back]')){state.intent=null;return renderTasks(modal,state);}if(actionTarget(event,'[data-persist]')){await storageDiagnostics(true);return renderDiagnostics(modal,state);}if(actionTarget(event,'[data-export-diagnostics]')){const payload={content_free:true,app_version:window.APP_VERSION||null,schema_version:48,storage:diag,counts:{materials:state.catalog.length,export_receipts:state.exportReceipts.length},statuses:state.catalog.reduce((out,x)=>(out[x.continuity_state]=(out[x.continuity_state]||0)+1,out),{})},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='linguistpro-import-center-diagnostics.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}};}
