  async function renderReference(modal){const body=modal.querySelector('#p2PortableBody'),actions=modal.querySelector('#p2PortableActions');actions.innerHTML='';body.innerHTML=`<section class="p4-reference"><h4>${tr('studio.importCenter.reference','Formats, storage and privacy')}</h4><article><b>Full ZIP</b><span>${tr('studio.importCenter.refFull','Complete local-device backup including material archives and local provenance.')}</span></article><article><b>Archive .lplp.zip</b><span>${tr('studio.importCenter.refArchive','One material with reachable immutable history; no media bytes.')}</span></article><article><b>Snapshot .lplp.zip</b><span>${tr('studio.importCenter.refSnapshot','One selected transcript/table state; no full history or media bytes.')}</span></article><article><b>Compatibility JSON</b><span>${tr('studio.importCenter.refCompatibility','Older text/table projection only. It never counts as a canonical backup.')}</span></article><article><b>${tr('studio.importCenter.localStorage','Local storage')}</b><span>${tr('studio.importCenter.refStorage','OPFS stays in this browser. Export a checked backup before device reset or deletion.')}</span></article><details><summary>${tr('studio.importCenter.technicalDetails','Technical details')}</summary><code>verify → no-write dry-run → explicit Apply → SAVEPOINT → receipt\nmedia: exact SHA-256 only\nprovider requests: 0 · server writes: 0</code></details></section>`;}
